-- Idempotent demo catalog. Run in the Supabase SQL editor.
-- These UUIDs exactly match starterProducts in app.js so fallback carts remain checkout-compatible.
on conflict (id) do update set name=excluded.name, brand=excluded.brand, category=excluded.category, description=excluded.description, specifications=excluded.specifications, price=excluded.price, original_price=excluded.original_price, stock=excluded.stock, image_url=excluded.image_url, rating=excluded.rating, is_active=excluded.is_active;
